/* =====================================================================
   Margin — Issue 14, Low Water
   Print-editorial system: paper, ink, hairline rules, asymmetric grid.
   ===================================================================== */

/* ---------- 1. tokens ---------- */

:root {
  --paper:      #f2efe6;
  --paper-sunk: #e7e2d4;
  --ink:        #16150f;
  --ink-soft:   #4a4739;
  --ink-faint:  #6f6a58;
  --rule:       rgba(22, 21, 15, .22);
  --rule-soft:  rgba(22, 21, 15, .11);
  --accent:     #9c3b1f;
  --accent-ink: #7c2c14;
  --accent-wash: rgba(156, 59, 31, .10);
  --shadow:     0 1px 0 rgba(22, 21, 15, .06);

  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua",
           "Hoefler Text", Georgia, ui-serif, serif;
  --sans:  system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue",
           Arial, sans-serif;
  --mono:  ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
           "Liberation Mono", monospace;

  --pad: clamp(18px, 4.5vw, 56px);
  --measure: 66ch;
  --ease: cubic-bezier(.2, .7, .2, 1);
}

[data-theme="night"] {
  --paper:      #131310;
  --paper-sunk: #1c1c18;
  --ink:        #e9e4d7;
  --ink-soft:   #b3ae9f;
  --ink-faint:  #8d887a;
  --rule:       rgba(233, 228, 215, .26);
  --rule-soft:  rgba(233, 228, 215, .13);
  --accent:     #e07a4d;
  --accent-ink: #f0a077;
  --accent-wash: rgba(224, 122, 77, .12);
  --shadow:     none;
}

/* ---------- 2. base ---------- */

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: 5.5rem;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(1rem, .55vw + .9rem, 1.15rem);
  line-height: 1.62;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  transition: background-color .35s var(--ease), color .35s var(--ease);
}

h1, h2, h3, p, ul, ol, blockquote, figure { margin: 0; }
ul, ol { padding: 0; list-style: none; }
img, svg { display: block; max-width: 100%; }

a {
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid var(--rule);
  padding-bottom: .04em;
  transition: border-color .2s var(--ease), color .2s var(--ease);
}
a:hover { border-color: var(--accent); color: var(--accent-ink); }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 1px;
}

.wrap {
  width: 100%;
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: var(--pad);
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  z-index: 100;
  background: var(--ink);
  color: var(--paper);
  padding: .7rem 1.1rem;
  font: 600 .8rem/1 var(--sans);
  border: 0;
}
.skip-link:focus {
  left: .6rem;
  top: .6rem;
}

/* ---------- 3. type helpers ---------- */

.eyebrow {
  font: 500 .68rem/1.2 var(--mono);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.eyebrow--end { text-align: right; }
.eyebrow--ok { color: var(--accent-ink); }

.margin-label {
  font: 500 .62rem/1.2 var(--mono);
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--accent-ink);
  margin-bottom: .5rem;
}

.byline {
  font: 400 .82rem/1.5 var(--sans);
  letter-spacing: .02em;
  color: var(--ink-soft);
  text-transform: uppercase;
}
.byline b { font-weight: 600; color: var(--ink); }
.byline__sep { color: var(--rule); margin: 0 .35em; }

.lede {
  font-size: 1.22em;
  line-height: 1.48;
  letter-spacing: -.005em;
  color: var(--ink);
  max-width: 34ch;
}

.section-head {
  display: flex;
  align-items: center;
  gap: 1.2rem;
  padding-bottom: .8rem;
  margin-bottom: clamp(1.6rem, 3vw, 2.8rem);
}
.section-head .eyebrow { flex: none; }

/* measuring rule: hairline with ticks */
.rule-measure {
  flex: 1 1 auto;
  height: 8px;
  border-top: 1px solid var(--rule);
  background-image: repeating-linear-gradient(
    to right,
    var(--rule) 0 1px,
    transparent 1px 12px
  );
  background-size: 12px 5px;
  background-repeat: repeat-x;
  background-position: 0 0;
}

/* ---------- 4. masthead ---------- */

.masthead {
  position: sticky;
  top: 0;
  z-index: 20;
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--rule-soft);
}
@supports not (background: color-mix(in srgb, red, blue)) {
  .masthead { background: var(--paper); }
}

.masthead__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 3.9rem;
  padding-block: .55rem;
}

.wordmark { border: 0; display: block; }
.wordmark__name {
  display: block;
  font-size: 1.42rem;
  line-height: 1;
  letter-spacing: -.02em;
  font-weight: 600;
}
.wordmark__name--lg { font-size: clamp(2.4rem, 7vw, 4.2rem); }
.wordmark__sub {
  display: block;
  margin-top: .18rem;
  font: 500 .58rem/1 var(--mono);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.masthead__nav {
  display: none;
  gap: clamp(.9rem, 2vw, 1.9rem);
  font: 400 .74rem/1 var(--sans);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.masthead__nav a { border: 0; padding-bottom: .15em; border-bottom: 1px solid transparent; }
.masthead__nav a:hover { border-bottom-color: var(--accent); }

.modes {
  display: flex;
  border: 1px solid var(--rule);
  border-radius: 999px;
  overflow: hidden;
  flex: none;
}
.modes__btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .38rem .7rem;
  border: 0;
  background: transparent;
  color: var(--ink-soft);
  font: 500 .64rem/1 var(--mono);
  letter-spacing: .14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color .2s var(--ease), color .2s var(--ease);
}
.modes__btn:hover { color: var(--ink); }
.modes__btn[aria-pressed="true"] {
  background: var(--ink);
  color: var(--paper);
}
.modes__dot {
  width: .5rem;
  height: .5rem;
  border-radius: 50%;
  border: 1px solid currentColor;
}
.modes__dot--paper { background: #f2efe6; }
.modes__dot--night { background: #131310; }

/* ---------- 5. hero ---------- */

.hero {
  position: relative;
  overflow: hidden;
  padding-top: clamp(1.6rem, 4vw, 3rem);
  padding-bottom: clamp(1rem, 3vw, 2rem);
}

.hero__meta {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: .55rem;
  border-bottom: 1px solid var(--ink);
  margin-bottom: clamp(1.4rem, 4vw, 3.2rem);
}

.hero__grid { display: grid; gap: clamp(1.4rem, 4vw, 2.4rem); }

.display {
  font-weight: 400;
  font-size: clamp(4.2rem, 19vw, 13.5rem);
  line-height: .82;
  letter-spacing: -.045em;
  display: grid;
}
.display__line { display: block; }
.display__line--2 {
  padding-left: clamp(1.2rem, 12vw, 12rem);
  font-style: italic;
}

/* the display motif: a waterline struck through the title */
.waterline {
  position: relative;
  display: block;
  height: 1.6rem;
  margin-top: -.2rem;
  border-top: 1px solid var(--accent);
}
.waterline__tick {
  position: absolute;
  top: -.15rem;
  font: 500 .58rem/1 var(--mono);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--accent-ink);
  background: var(--paper);
  padding: 0 .4rem;
}
.waterline__tick--l { left: 0; }
.waterline__tick--r { right: 0; }

.hero__aside { display: grid; gap: 1rem; align-content: start; }
.standfirst {
  font-size: 1.16em;
  line-height: 1.42;
  max-width: 30ch;
  text-wrap: pretty;
}
.hero__note {
  font-size: .94em;
  color: var(--ink-soft);
  max-width: 46ch;
  padding-top: .9rem;
  border-top: 1px solid var(--rule-soft);
}

/* ---------- 6. the bed: inline SVG motif ---------- */

.motif {
  margin-top: clamp(1.4rem, 4vw, 2.6rem);
  border-top: 1px solid var(--rule-soft);
  padding-top: clamp(1rem, 2.5vw, 1.6rem);
}
.motif__svg { width: 100%; height: clamp(150px, 26vw, 300px); }
.motif__strata path {
  fill: none;
  stroke: var(--rule);
  stroke-width: 1.15;
}
.motif__high {
  fill: none;
  stroke: var(--ink-faint);
  stroke-width: 1;
  stroke-dasharray: 7 6;
  opacity: .8;
}
.motif__now {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.6;
}
.motif__ticks line {
  stroke: var(--accent);
  stroke-width: 1;
  opacity: .55;
}
.motif__label {
  font: 500 15px/1 var(--mono);
  letter-spacing: .16em;
  text-transform: uppercase;
  fill: var(--ink-faint);
}
.motif__label--accent { fill: var(--accent-ink); }

/* ---------- 7. cover story ---------- */

.cover { padding-top: clamp(3rem, 8vw, 6rem); }
.cover__grid { display: grid; gap: clamp(1.8rem, 4vw, 3rem); }

.cover__title {
  font-weight: 400;
  font-size: clamp(2.3rem, 7.2vw, 5rem);
  line-height: .96;
  letter-spacing: -.03em;
  max-width: 20ch;
  text-wrap: balance;
}
.cover__body > .byline { margin-top: 1.1rem; padding-bottom: 1.3rem; border-bottom: 1px solid var(--rule-soft); }
.cover__body > p { margin-top: 1.2rem; max-width: var(--measure); }
.cover__body > .lede { margin-top: 1.6rem; }

.excerpt {
  margin-top: 1.8rem;
  border-top: 1px solid var(--ink);
  max-width: var(--measure);
}
.excerpt summary {
  cursor: pointer;
  list-style: none;
  padding: .9rem 0;
  font: 500 .68rem/1.2 var(--mono);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--accent-ink);
  display: flex;
  align-items: center;
  gap: .6rem;
}
.excerpt summary::-webkit-details-marker { display: none; }
.excerpt summary::before {
  content: "+";
  font: 400 1.05rem/1 var(--mono);
}
.excerpt[open] summary::before { content: "\2013"; }
.excerpt__body { padding-bottom: .4rem; border-top: 1px solid var(--rule-soft); }
.excerpt__body p { margin-top: 1.1rem; color: var(--ink-soft); }

.cover__margin {
  display: grid;
  gap: 0;
  align-content: start;
  border-top: 3px solid var(--ink);
  padding-top: 1.1rem;
}
.cover__margin > * + * { margin-top: 1.4rem; }
.pullquote {
  font-size: 1.34em;
  line-height: 1.34;
  letter-spacing: -.015em;
  text-indent: -.4em;
}
.pullquote footer {
  margin-top: .7rem;
  font: 500 .64rem/1.4 var(--mono);
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-faint);
}
.margin-note {
  font: 400 .84rem/1.6 var(--sans);
  color: var(--ink-soft);
  max-width: 34ch;
}

/* ---------- 8. also inside ---------- */

.stories { padding-top: clamp(3rem, 8vw, 6rem); }
.stories__list { display: grid; gap: clamp(2rem, 5vw, 3rem); }

.story article {
  border-top: 1px solid var(--ink);
  padding-top: 1rem;
}
.story__mark {
  width: clamp(88px, 22vw, 132px);
  height: auto;
  margin-bottom: 1.1rem;
  fill: none;
  stroke: var(--ink-soft);
  stroke-width: 1.4;
  overflow: visible;
}
.story__mark-fill { fill: var(--accent-wash); stroke: none; }
.story__mark-hollow { fill: none; stroke: var(--accent); stroke-width: 1.6; }

.story__num {
  font: 500 .66rem/1 var(--mono);
  letter-spacing: .22em;
  color: var(--accent-ink);
  margin-bottom: .5rem;
}
.story__title {
  font-weight: 400;
  font-size: clamp(1.5rem, 3.4vw, 2.35rem);
  line-height: 1.06;
  letter-spacing: -.022em;
  text-wrap: balance;
}
.story__byline {
  margin-top: .5rem;
  font: 500 .66rem/1.3 var(--mono);
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--ink-faint);
}
.story__text {
  margin-top: .8rem;
  max-width: 38ch;
  color: var(--ink-soft);
  font-size: .97em;
}

/* ---------- 9. archive ---------- */

.archive { padding-top: clamp(3rem, 8vw, 6rem); }
.archive__strip {
  display: grid;
  gap: 0;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
}
.back {
  padding: 1.1rem 0;
  border-bottom: 1px solid var(--rule-soft);
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: .3rem .9rem;
}
.back:last-child { border-bottom: 0; }
.back__num {
  font: 400 1.9rem/1 var(--serif);
  color: var(--accent-ink);
  flex: none;
  min-width: 2.4ch;
}
.back__title {
  font-weight: 400;
  font-size: 1.12rem;
  line-height: 1.2;
  letter-spacing: -.01em;
}
.back__meta {
  margin-left: auto;
  font: 500 .62rem/1.4 var(--mono);
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-faint);
  white-space: nowrap;
}
.archive__foot {
  margin-top: .9rem;
  font: 400 .8rem/1.5 var(--sans);
  color: var(--ink-soft);
}

/* ---------- 10. subscribe ---------- */

.subscribe { padding: clamp(3rem, 8vw, 6rem) 0 clamp(3rem, 7vw, 5rem); }
.subscribe__grid { display: grid; gap: clamp(2rem, 5vw, 3.4rem); }

.offer__title {
  font-weight: 400;
  font-size: clamp(1.9rem, 5vw, 3.4rem);
  line-height: 1.02;
  letter-spacing: -.028em;
  max-width: 22ch;
}
.offer__price {
  margin-top: 1.4rem;
  display: flex;
  align-items: baseline;
  gap: .7rem;
  border-bottom: 1px solid var(--rule-soft);
  padding-bottom: 1.1rem;
}
.offer__amount {
  font-size: clamp(2rem, 5vw, 3rem);
  line-height: 1;
  letter-spacing: -.02em;
  color: var(--accent-ink);
}
.offer__unit {
  font: 500 .66rem/1 var(--mono);
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--ink-faint);
}
.offer__list {
  margin-top: 1.3rem;
  display: grid;
  gap: .55rem;
  max-width: 44ch;
}
.offer__list li {
  font-size: .96em;
  color: var(--ink-soft);
  padding-left: 1.4rem;
  position: relative;
}
.offer__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: .78em;
  width: .8rem;
  height: 1px;
  background: var(--accent);
}
.offer__fine {
  margin-top: 1.4rem;
  font: 400 .76rem/1.6 var(--sans);
  color: var(--ink-faint);
  max-width: 40ch;
}

.signup {
  background: var(--paper-sunk);
  border: 1px solid var(--rule-soft);
  padding: clamp(1.2rem, 3vw, 2rem);
  align-self: start;
}
.field { display: grid; }
.field__label {
  font: 500 .62rem/1.2 var(--mono);
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--ink-soft);
  margin-bottom: .6rem;
}
.field__input {
  width: 100%;
  font: 400 1rem/1.4 var(--serif);
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: .8rem .9rem;
  transition: border-color .2s var(--ease), box-shadow .2s var(--ease);
}
.field__input::placeholder { color: var(--ink-faint); }
.field__input:hover { border-color: var(--ink-faint); }
.field__input:focus-visible { outline: none; border-color: var(--accent); box-shadow: inset 0 -2px 0 var(--accent); }
.field__input[aria-invalid="true"] { border-color: var(--accent); box-shadow: inset 0 -2px 0 var(--accent); }
.field__note {
  margin-top: .7rem;
  font: 400 .74rem/1.55 var(--sans);
  color: var(--ink-faint);
}
.field__error {
  margin-top: .7rem;
  font: 500 .74rem/1.55 var(--sans);
  color: var(--accent-ink);
  display: flex;
  gap: .45rem;
}
.field__error::before { content: "\2192"; }

.btn {
  margin-top: 1.4rem;
  width: 100%;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: var(--paper);
  font: 500 .68rem/1 var(--mono);
  letter-spacing: .2em;
  text-transform: uppercase;
  padding: 1rem 1.1rem;
  cursor: pointer;
  border-radius: 0;
  transition: background-color .2s var(--ease), color .2s var(--ease), transform .12s var(--ease);
}
.btn:hover { background: var(--accent); border-color: var(--accent); color: var(--paper); }
.btn:active { transform: translateY(1px); }
.btn--ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--rule);
  width: auto;
}
.btn--ghost:hover { color: var(--paper); }

.signup__done { display: grid; }
.signup__done-title {
  margin-top: .6rem;
  font-weight: 400;
  font-size: clamp(1.3rem, 3.4vw, 1.9rem);
  line-height: 1.14;
  letter-spacing: -.02em;
}
.signup__done-title:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
.signup__done-text {
  margin-top: .9rem;
  font: 400 .88rem/1.6 var(--sans);
  color: var(--ink-soft);
}
.signup__echo { color: var(--ink); border-bottom: 1px solid var(--rule); }
.signup__status {
  margin-top: 1rem;
  min-height: 1.2rem;
  font: 500 .72rem/1.5 var(--mono);
  letter-spacing: .1em;
  color: var(--accent-ink);
}
.signup__status:empty { margin-top: 0; }

/* ---------- 11. colophon ---------- */

.colophon {
  border-top: 1px solid var(--ink);
  padding-top: clamp(2rem, 5vw, 3.4rem);
  padding-bottom: 2.4rem;
}
.colophon__grid { display: grid; gap: clamp(1.6rem, 4vw, 2.6rem); }
.colophon__cols { display: grid; gap: 1.6rem; align-content: start; }
.colophon__text {
  margin-top: .7rem;
  font: 400 .8rem/1.65 var(--sans);
  color: var(--ink-soft);
}
.colophon__rule {
  max-width: 1280px;
  margin: clamp(1.6rem, 4vw, 2.6rem) auto 0;
  padding-inline: var(--pad);
  height: 7px;
  border-top: 1px solid var(--rule);
}
.colophon__rule::before { content: none; }

/* ---------- 12. layout at width ---------- */

@media (min-width: 700px) {
  .masthead__nav { display: flex; }
  .stories__list { grid-template-columns: repeat(6, 1fr); }
  .story--a { grid-column: 1 / span 3; }
  .story--b { grid-column: 4 / span 3; margin-top: clamp(1.4rem, 4vw, 3.4rem); }
  .story--c { grid-column: 2 / span 4; }
  .archive__strip { grid-template-columns: repeat(3, 1fr); }
  .back {
    border-bottom: 0;
    border-left: 1px solid var(--rule-soft);
    padding: 1.2rem 1.3rem 1.4rem 0;
    flex-direction: column;
    gap: .45rem;
  }
  .back:first-child { padding-left: 0; border-left: 0; }
  .back:not(:first-child) { padding-left: 1.3rem; }
  .back__meta { margin-left: 0; }
  .colophon__grid { grid-template-columns: 1.4fr 1fr; }
  .colophon__cols { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1000px) {
  .hero__grid {
    grid-template-columns: repeat(12, 1fr);
    column-gap: clamp(16px, 2vw, 32px);
    align-items: end;
  }
  .hero__grid .display { grid-column: 1 / span 8; }
  .hero__aside {
    grid-column: 10 / span 3;
    padding-bottom: .6rem;
    border-top: 3px solid var(--ink);
    padding-top: 1rem;
  }
  .waterline { margin-top: -1.4rem; }

  .cover__grid {
    grid-template-columns: repeat(12, 1fr);
    column-gap: clamp(16px, 2vw, 32px);
  }
  .cover__body { grid-column: 1 / span 7; }
  .cover__margin {
    grid-column: 9 / span 4;
    position: sticky;
    top: 6rem;
  }

  .stories__list { column-gap: clamp(16px, 2vw, 32px); }
  .stories__list { grid-template-columns: repeat(12, 1fr); }
  .story--a { grid-column: 1 / span 5; }
  .story--b { grid-column: 7 / span 4; margin-top: clamp(2rem, 6vw, 5rem); }
  .story--c { grid-column: 3 / span 5; margin-top: clamp(1rem, 3vw, 2rem); }

  .subscribe__grid {
    grid-template-columns: repeat(12, 1fr);
    column-gap: clamp(16px, 2vw, 32px);
    align-items: start;
  }
  .offer { grid-column: 1 / span 6; }
